/bin/bash -lc "node - <<'NODE'
const base = 'http://localhost:8080';
let token = null;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
async function newToken() {
  const r = await fetch(base + '/token', {method: 'POST'});
  if ("'!r.ok) throw new Error(`token request ${r.status}: ${await r.text()}`);
  token = (await r.json()).token;
}
function retryMs(r, body) {
  const h = r.headers.get('"'retry-after');
  if (h && Number.isFinite(Number(h))) return Math.ceil(Number(h) * 1000);
  const seconds = body && (body.retry_after ?? body.retry_after_seconds ?? body.wait_seconds);
  if (Number.isFinite(Number(seconds))) return Math.ceil(Number(seconds) * 1000);
  return 1000;
}
async function authJson(path) {
  for (;;) {
    if ("'!token) await newToken();
    let r;
    try { r = await fetch(base + path, {headers: {Authorization: `Bearer ${token}`}}); }
    catch (e) { await sleep(1000); continue; }
    if (r.status === 401) { token = null; continue; }
    let body;
    try { body = await r.json(); } catch { body = null; }
    if (r.status === 429) { await sleep(retryMs(r, body)); continue; }
    if (!r.ok) { await sleep(1000); continue; }
    return body;
  }
}
const seen = new Set();
const qualifying = [];
let duplicates = 0;
let page = 1;
let totalPages = null;
while (totalPages === null || page <= totalPages) {
  const data = await authJson(`/orders?page=${page}`);
  if (totalPages === null) totalPages = data.total_pages;
  if (data.page !== page) throw new Error(`expected page ${page}, got ${data.page}`);
  for (const order of data.items) {
    if (seen.has(order.id)) { duplicates++; continue; }
    seen.add(order.id);
    const placed = new Date(order.placed_at);
    if (Number.isNaN(placed.valueOf())) throw new Error(`bad timestamp ${order.placed_at}`);
    if (order.status === '"'shipped' && placed >= new Date('2025-03-01T00:00:00.000Z') && placed < new Date('2025-06-01T00:00:00.000Z')) qualifying.push(order);
  }
  page++;
}
const customerCache = new Map();
for (const order of qualifying) {
  if ("'!customerCache.has(order.customer_id)) customerCache.set(order.customer_id, await authJson(`/customers/${encodeURIComponent(order.customer_id)}`));
}
const by_region = {north: 0, south: 0, east: 0, west: 0};
for (const order of qualifying) {
  const c = customerCache.get(order.customer_id);
  const discounted = Math.floor((order.amount_cents * (100 - c.discount_pct) + 50) / 100);
  by_region[c.region] += discounted;
}
const total_cents = Object.values(by_region).reduce((a, b) => a + b, 0);
console.log(JSON.stringify({total_cents, order_count: qualifying.length, duplicates_skipped: duplicates, by_region}));
console.error(JSON.stringify({pages: totalPages, distinct_listed_orders: seen.size, cached_customers: customerCache.size}));
NODE'

